 function cameraTools(track){const target=root?.querySelector('[data-qp-camera-tools]');if(!target)return;let caps={},settings={};try{caps=track?.getCapabilities?.()||{};settings=track?.getSettings?.()||{};}catch{}const parts=[];if(caps.torch)parts.push(button('Encender luz','data-qp-camera-light aria-pressed="false"'));if(caps.focusMode?.some(x=>['single-shot','continuous'].includes(x)))parts.push(button('Enfocar','data-qp-camera-focus'));if(Number.isFinite(caps.zoom?.min)&&Number.isFinite(caps.zoom?.max)&&caps.zoom.max>caps.zoom.min){const min=caps.zoom.min,max=Math.max(min,Math.min(caps.zoom.max,3)),value=Math.max(min,Math.min(max,settings.zoom||min));if(max>min)parts.push('<label>Zoom <output data-qp-zoom-value>'+value.toFixed(1)+'×</output><input aria-label="Zoom de la cámara" data-qp-camera-zoom type="range" min="'+min+'" max="'+max+'" step="'+(caps.zoom.step||0.1)+'" value="'+value+'"></label>');}target.innerHTML=parts.join('');target.hidden=!parts.length;}
 async function adjustCamera(option,value){const track=stream?.getVideoTracks()[0];if(!track)throw Error('Activa la cámara primero.');const caps=track.getCapabilities?.()||{};let requested;if(option==='torch'&&caps.torch)requested={torch:!!value};else if(option==='focusMode'&&caps.focusMode?.some(x=>['single-shot','continuous'].includes(x)))requested={focusMode:caps.focusMode.includes('single-shot')?'single-shot':'continuous'};else if(option==='zoom'&&Number.isFinite(value)&&Number.isFinite(caps.zoom?.min)&&Number.isFinite(caps.zoom?.max))requested={zoom:Math.max(caps.zoom.min,Math.min(caps.zoom.max,3,value))};else throw Error('Este ajuste no está disponible en tu cámara.');try{await track.applyConstraints({advanced:[requested]});}catch{throw Error('La cámara no pudo aplicar el ajuste. Prueba otra distancia o cambia de cámara.');}return stream?.getVideoTracks()[0]===track;}
